/* ------------------------------------------------------------------ public API (in-process) */

/** What other modules may call in-process: `ctx.use('advertising')` (or `ctx.tryUse` for an optional dependency). */
export interface AdvertisingPublicApi {
  /** Sponsored product cards and their positions for a results list (max per page from the placement; relevance first, then priority). Only eligible, in-stock offers are returned. personalizationAllowed false: only page context (query, category, product) is used, frequency state is kept per session only and clicks are not kept for attribution by visitor; customerId (signed-in shopper) lets frequency caps and attribution follow the customer across devices when personalization is allowed. Used by: search, catalog. */
  sponsoredForResults(ctx: { page: PageType, query?: string, categoryId?: string, productId?: string, visitorId: string, sessionId: string, device: string, organicOfferIds: string[], personalizationAllowed: boolean, customerId?: string }): Promise<SponsoredProductSlot[]>;
  /** Ad positions on a page, so content can show them as locked markers in homepage sections. Used by: content. */
  adPositionsFor(page: PageType): Promise<{ placementKey: string, name: string, enabled: boolean }[]>;
  /** Ads linked to a promotion (shown on the promotion detail). Used by: promotions, graphql. */
  campaignsForPromotion(promotionId: string): Promise<AdCampaignSummary[]>;
  /** True for checkout, payment results, order tracking and returns; used by front-end shells to skip the serve call. Used by: content. */
  isAdBlockedPage(page: PageType): Promise<boolean>;
  /** Displays, clicks, dismissals, attributed purchases and spend per campaign and day, from the daily_stats read model (days still open are marked partial). Used by: reports. */
  dailyPerformance(range: common.DateRange, filter?: { campaignId?: string, sellerId?: string }): Promise<CampaignDayPerformance[]>;
  /** Read-only advertising summary for the Admin dashboard tile: live now (own and paid), starting in 7 days, ending soon, waiting approval, spend this month and short campaign lists. Records nothing; ad serving stays on POST /api/store/advertising/decisions. Used by: graphql, reports. */
  dashboardSummary(opts?: { listLimit?: number }): Promise<AdsDashboard>;
}

/* ------------------------------------------------------------------ tables (Kysely row types) */

/** Tables in the `advertising` schema. Use with `ctx.db` (already scoped to the schema). */
export interface AdvertisingDb {
  /** One row per placement type with its rules */
  placements: {
    id: string;
    key: string;
    name: string;
    kind: string;
    enabled: boolean;
    availability: string;
    eligible_pages: Json;
    formats: Json;
    frequency_cap: Json | null;
    trigger: Json | null;
    rotation: Json;
    dismissal: Json;
    max_per_page: number | null;
    positions: Json | null;
    label: string;
    description: string;
    version: number;
    updated_by: string | null;
    updated_at: Date;
  };
  /** Versioned global rules; current = highest effective version */
  global_rules: {
    version: number;
    rules: Json;
    effective_at: Date;
    approval_request_id: string | null;
    created_by: string;
    created_at: Date;
  };
  campaigns: {
    id: string;
    ref: string;
    name: string;
    origin: 'staff' | 'seller_request';
    advertiser_kind: string;
    seller_id: string | null;
    brand_id: string | null;
    goal: string;
    owner_staff_id: string | null;
    linked_promotion_id: string | null;
    placement_id: string;
    pages: Json;
    page_category_ids: Json;
    audience: Json;
    destination: Json;
    starts_at: Date | null;
    ends_at: Date | null;
    time_zone: string;
    frequency_cap: Json;
    dismissal: Json;
    priority: number;
    billing: string;
    rate: number | null;
    daily_limit: number | null;
    total_limit: number | null;
    delivery_cap: number | null;
    spent: number;
    currency: string;
    stop_with_promotion: boolean;
    after_approval: 'schedule' | 'activate';
    status: string;
    paused_reason: string | null;
    finished_reason: string | null;
    note_to_reviewers: string | null;
    created_by: string;
    created_at: Date;
    updated_at: Date;
    version: number;
  };
  /** Promoted offers, products, stores or brands */
  campaign_items: {
    campaign_id: string;
    kind: string;
    target_id: string;
    label: string | null;
  };
  campaign_creatives: {
    campaign_id: string;
    creative_id: string;
    device: string;
  };
  /** Required reviewers per campaign submission */
  approval_steps: {
    id: string;
    campaign_id: string;
    submission: number;
    role: string;
    reviewer_id: string | null;
    state: string;
    note: string | null;
    decided_at: Date | null;
  };
  /** Creative library */
  creatives: {
    id: string;
    advertiser_kind: string;
    seller_id: string | null;
    brand_id: string | null;
    kind: string;
    device: string;
    placement_key: string;
    media_id: string | null;
    file_name: string | null;
    width: number | null;
    height: number | null;
    bytes: number | null;
    duration_seconds: number | null;
    headline: string | null;
    body: string | null;
    button_text: string | null;
    link: string | null;
    status: string;
    link_check: Json;
    auto_checks: Json;
    created_by: string;
    created_at: Date;
  };
  creative_reviews: {
    id: string;
    creative_id: string;
    reviewer_id: string;
    role: string;
    decision: string;
    reason_code: string | null;
    comment: string | null;
    at: Date;
  };
  /** Lifecycle timeline with actor and reason */
  campaign_log: {
    id: string;
    campaign_id: string;
    action: string;
    from_status: string | null;
    to_status: string | null;
    reason: string | null;
    actor_kind: string;
    actor_id: string | null;
    at: Date;
  };
  /** Displays, clicks, dismissals (append-only, partitioned by day; retained 13 months) */
  ad_events: {
    id: string;
    impression_id: string;
    campaign_id: string;
    creative_id: string;
    placement_key: string;
    kind: string;
    /** hashed */
    visitor_key: string;
    session_id: string;
    customer_id: string | null;
    page: string;
    device: string;
    at: Date;
    cost: number | null;
  };
  /** Per visitor and campaign counters and suppression (TTL-cleaned) */
  frequency_state: {
    visitor_key: string;
    campaign_id: string;
    session_id: string | null;
    session_displays: number;
    window_displays: number;
    window_started_at: Date;
    last_display_at: Date | null;
    suppressed_until: Date | null;
  };
  /** Orders attributed to a click within the attribution period */
  attributions: {
    id: string;
    order_id: string;
    campaign_id: string;
    click_event_id: string;
    amount: number;
    currency: string;
    attributed_at: Date;
    reversed: boolean;
  };
  /** Read model per campaign and day */
  daily_stats: {
    campaign_id: string;
    day: string;
    displays: number;
    clicks: number;
    dismissals: number;
    spend: number;
    attributed_orders: number;
    attributed_sales: number;
  };
  /** Seller ad charges per campaign and day, posted to finance as a separate statement line */
  ad_charges: {
    id: string;
    campaign_id: string;
    seller_id: string;
    day: string;
    basis: string;
    units: number;
    rate: number;
    amount: number;
    currency: string;
    state: string;
    posted_at: Date | null;
    ledger_entry_id: string | null;
    statement_ref: string | null;
    reason: string | null;
  };
}

