  events: {
    publishes: {
      "advertising.campaign.status_changed": { when: "Any lifecycle transition (submitted, approved, scheduled, live, paused, finished, archived, rejected)", payload: () => AdvertisingCampaignStatusChangedEvent },
      "advertising.creative.reviewed": { when: "A reviewer decides on a creative", payload: () => AdvertisingCreativeReviewedEvent },
      "advertising.placement.updated": { when: "A placement's rules or on/off change", payload: () => AdvertisingPlacementUpdatedEvent },
      "advertising.charge.posted": { when: "Daily seller ad charges are posted for seller statements", payload: () => AdvertisingChargePostedEvent },
      "advertising.charge.credited": { when: "A posted charge is credited or an accrued one voided", payload: () => AdvertisingChargeCreditedEvent },
      "advertising.budget.reached": { when: "A paid campaign reaches its daily or total spending limit", payload: () => AdvertisingBudgetReachedEvent },
      "advertising.campaign.ending_soon": { when: "A live or scheduled campaign ends within endingSoonDays (daily, once per campaign)", payload: () => AdvertisingCampaignEndingSoonEvent },
    },
    consumes: {
      "promotions.campaign.ended": "Finish linked ads with stopWithPromotion (reason promotion_ended)",
      "promotions.campaign.paused": "Pause linked ads until the promotion resumes",
      "promotions.campaign.resumed": "Resume ads paused because of the promotion",
      "offers.offer.status_changed": "Pause ads whose promoted offer is no longer active (offer_unavailable)",
      "inventory.stock.low": "Pause sponsored ads below the minimum stock threshold",
      "inventory.stock.changed": "Resume system-paused ads when stock returns above the threshold",
      "catalog.product.publication_changed": "Pause ads promoting hidden or suspended products",
      "sellers.seller.restricted": "Pause the seller's ads when the restriction covers new sales or advertising",
      "sellers.seller.suspended": "Finish the seller's ads (seller_restricted); charges only for delivery so far",
      "trust.enforcement.recorded": "Revoke creatives and reject requests that promote the enforced offer or product; the enforcementId is stored with the revoke or reject reason so a reversal can find them",
      "trust.enforcement.reversed": "Inbox-claimed per event. Creatives revoked by that enforcementId go back to in_review (reinstate) and seller requests it rejected reopen as drafts (reopen) the seller may resubmit; ads finished because of it are not restarted. The seller (or staff owner) is told; the campaign log records the reversal",
      "orders.order.placed": "Attribute the order to the last ad click within attributionDays: by customerId for signed-in shoppers, and for guests by the payload visitorId (present only when the shopper allowed personalization; hashed like ad_events.visitor_key). Orders with neither are not attributed. unique (order_id, campaign_id) keeps redelivery idempotent",
      "orders.item.cancelled": "Reduce attributed sales for cancelled items",
      "content.page.published": "Re-run link checks for creatives pointing at the page",
      "access.approval.decided": "Apply an approved global rules change at its effective time (and finish non-draft fee schedule approvals). Inbox-claimed per event (ctx.inbox) before acting, so a redelivered decision applies once and writes one audit entry",
      "catalog.product.merged": "Repoint ads, ad requests and creatives that promote the duplicate product (or its variants, mapped through newVariantId / intoVariantId) to the kept product; delivery, spend and attribution history stay on the ad"
    },
  },
  jobs: {
    "advertising.start-due": {
      "schedule": "every 1 min",
      "does": "Scheduled campaigns past startsAt → live"
    },
    "advertising.finish-due": {
      "schedule": "every 1 min",
      "does": "Live or paused campaigns past endsAt → finished; finish when delivery cap reached"
    },
    "advertising.availability-sweep": {
      "schedule": "every 5 min",
      "does": "Pause ads for unavailable or low-stock promoted offers and inactive linked promotions; resume when available again"
    },
    "advertising.link-check": {
      "schedule": "hourly",
      "does": "Re-check destination links and promoted-offer availability for approved and live creatives"
    },
    "advertising.stats-rollup": {
      "schedule": "every 5 min",
      "does": "Aggregate ad_events into daily_stats"
    },
    "advertising.accrue-charges": {
      "schedule": "every 15 min",
      "does": "Accrue billable clicks/displays and fixed daily fees, capped at daily and total limits; stop delivery at the limit"
    },
    "advertising.post-charges": {
      "schedule": "daily 02:00 market time",
      "does": "Post the previous day's charges to finance (advertising.charge.posted)"
    },
    "advertising.expire-frequency-state": {
      "schedule": "hourly",
      "does": "Delete frequency and suppression rows past their window"
    },
    "advertising.ending-soon-notice": {
      "schedule": "daily 08:00 market time",
      "does": "Publish advertising.campaign.ending_soon for campaigns ending within endingSoonDays (once per campaign), so owners finish or renew deliberately"
    }
  },
